// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 unlockTime, uint256 value, address actor) public {
        vm.assume(value <= VALUE_CAP);
        vm.assume(actor != address(0));
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 365 days);
        value = bound(value, 0, 1 ether);
        vm.deal(actor, value);

        vm.prank(actor);
        c.Put{value: value}(unlockTime);

        (, uint256 balance) = c.Acc(actor);
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime == unlockTime && balance == value);
    }
}
